import Mathlib

open FreeGroup

/-- Show that the group given by the presentation $\langle a, b \mid a^5 = b^2 = 1,\; ba = a^2 b \rangle$ is isomorphic to $\mathbb{Z}_2$. -/
theorem group_presentation_iso_z2 :
  let a := FreeGroup.of (0 : Fin 2)
  let b := FreeGroup.of (1 : Fin 2)
  let rels : Set (FreeGroup (Fin 2)) := {a^5, b^2, b * a * (a^2 * b)⁻¹}
  Nonempty (PresentedGroup rels ≃* ZMod 2) := by
  sorry

import Mathlib

open Matrix

/-- Show that the set $G$ of all real $2 \times 2$ matrices of the form 
$\left( \begin{matrix} a&b\\ 0&c \end{matrix} \right)$ is a subgroup of $\mathrm{GL}(2)$. 
Let $N$ be the set of all matrices of the form $\left( \begin{matrix} 1&b\\ 0&1 \end{matrix} \right).$ 
Prove that $N \triangleleft\, G$. (Note that you need to show it is a subgroup as well as prove that it is normal.) -/
theorem srdoty_alg_quotient_gps_341 :
    let G : Subgroup (GeneralLinearGroup (Fin 2) ℝ) :=
      { carrier := {M | M.1 1 0 = 0}
        mul_mem' := by sorry
        one_mem' := by sorry
        inv_mem' := by sorry }
    let N : Subgroup (GeneralLinearGroup (Fin 2) ℝ) :=
      { carrier := {M | M.1 0 0 = 1 ∧ M.1 1 0 = 0 ∧ M.1 1 1 = 1}
        mul_mem' := by sorry
        one_mem' := by sorry
        inv_mem' := by sorry }
    (N ≤ G) ∧ N.Normal := by sorry

import Mathlib

open Matrix

/-- Let $G=\left\{\begin{bmatrix} a & -b\\ b & a \end{bmatrix}: a,b\in\mathbb{R}\right\}$ and let $G'=G\setminus\left\{\begin{bmatrix}0&0\\0&0\end{bmatrix}\right\}$. Prove that $G'$ is a group under matrix multiplication. -/
theorem srdoty_alg_abstract_gps_619 :
  let G : Set (Matrix (Fin 2) (Fin 2) ℝ) := 
    {M | ∃ a b : ℝ, M = !![a, -b; b, a]}
  let G' : Set (Matrix (Fin 2) (Fin 2) ℝ) := 
    G \ {0}
  ∃ _ : Group G', True := by sorry
